steps.run:
POSTGRES_SUPABASE_VERSION=${{ steps.build-ami.outputs.postgres_release_version }}
echo "::notice title=AMI Published::Postgres AMI version: $POSTGRES_SUPABASE_VERSION"
{
  echo "PACKER_EXECUTION_ID=${{ steps.build-ami.outputs.execution_id }}"
  echo "POSTGRES_MAJOR_VERSION=${{ matrix.postgres_version }}"
  echo "POSTGRES_SUPABASE_VERSION=$POSTGRES_SUPABASE_VERSION"
} >>"$GITHUB_ENV"

if [ "${{ matrix.target.arch }}" = "amd64" ]; then
  {
    echo "ARCH_SUFFIX=-x86"
    echo "RELEASE_TAG=${POSTGRES_SUPABASE_VERSION}-x86"
  } >>"$GITHUB_ENV"
else
  {
    echo "ARCH_SUFFIX="
    echo "RELEASE_TAG=${POSTGRES_SUPABASE_VERSION}"
  } >>"$GITHUB_ENV"
fi

nix run nixpkgs#nushell -- -c 'let versions = (open ansible/vars.yml | get postgres_major)
let base_matrix = ($versions | each { |ver|
  let version = ($ver | str trim)
  let dockerfile = $"Dockerfile-($version)"
  if ($dockerfile | path exists) {
    {
      version: $version,
      dockerfile: $dockerfile,
      target: "production"
    }
  } else {
    null
  }
} | compact)

# Discover multigres variants by checking for matching targets in Dockerfile-multigres
let multigres_matrix = ($versions | each { |ver|
  let version = ($ver | str trim)
  let mg_version = $"multigres-($version)"
  let mg_dockerfile = "Dockerfile-multigres"
  let mg_target = $"variant-($version)"
  if ($mg_dockerfile | path exists) and (open --raw $mg_dockerfile | str contains $"AS ($mg_target)") {
    {
      version: $mg_version,
      dockerfile: $mg_dockerfile,
      target: $mg_target
    }
  } else {
    null
  }
} | compact)

let matrix = ($base_matrix | append $multigres_matrix)

let matrix_config = {
  include: $matrix
}

$"matrix_config=($matrix_config | to json -r)" | save --append $env.GITHUB_OUTPUT'

nix run nixpkgs#nushell -- -c '
  open ansible/vars.yml 
  | items { |key value| {name: $key, item: $value} } 
  | where { |it| ($it.item | describe) == "string" } 
  | each { |it| $"($it.name)=($it.item)" } 
  | str join "\n" 
  | save --append $env.GITHUB_OUTPUT
'

if [[ "${{ matrix.arch }}" == "arm64" ]]; then
  pg_version=$(nix run nixpkgs#nushell -- -c '
    let version = "${{ matrix.postgres.version }}"
    let is_multigres = ($version | str starts-with "multigres-")
    let base_version = if $is_multigres { $version | str replace "multigres-" "" } else { $version }
    let release_key = if ($base_version | str contains "orioledb") {
      $"postgresorioledb-17"
    } else {
      $"postgres($base_version)"
    }
    let base_tag = (open ansible/vars.yml | get postgres_release | get $release_key | str trim)
    if $is_multigres { $"($base_tag)-multigres" } else { $base_tag }
  ')
  echo "pg_version=supabase/postgres:$pg_version" >> $GITHUB_OUTPUT
else
  pg_version=$(nix run nixpkgs#nushell -- -c '
    let version = "${{ matrix.postgres.version }}"
    let is_multigres = ($version | str starts-with "multigres-")
    let base_version = if $is_multigres { $version | str replace "multigres-" "" } else { $version }
    let release_key = if ($base_version | str contains "orioledb") {
      $"postgresorioledb-17"
    } else {
      $"postgres($base_version)"
    }
    let base_tag = (open ansible/vars.yml | get postgres_release | get $release_key | str trim)
    if $is_multigres { $"($base_tag)-multigres" } else { $base_tag }
  ')
  echo "pg_version=supabase/postgres:$pg_version" >> $GITHUB_OUTPUT
fi

nix run nixpkgs#nushell -- -c '
  let version = "${{ matrix.version }}"
  let is_multigres = ($version | str starts-with "multigres-")
  let base_version = if $is_multigres { $version | str replace "multigres-" "" } else { $version }
  let release_key = if ($base_version | str contains "orioledb") {
    $"postgresorioledb-17"
  } else {
    $"postgres($base_version)"
  }
  let base_tag = (open ansible/vars.yml | get postgres_release | get $release_key | str trim)
  let pg_version = if $is_multigres { $"($base_tag)-multigres" } else { $base_tag }
  $"pg_version=supabase/postgres:($pg_version)" | save --append $env.GITHUB_OUTPUT
'

nix run nixpkgs#nushell -- -c '
  # Parse the matrix configuration directly
  let matrix_config = (${{ toJson(needs.prepare.outputs.matrix_config) }} | from json)

  # Get versions directly from include array
  let versions = ($matrix_config.include | get version)

  echo "Versions: $versions"

  # Convert the versions to a comma-separated string
  let versions_str = ($versions | str join ",")
  $"versions=$versions_str" | save --append $env.GITHUB_ENV
'

nix run nixpkgs#nushell -- -c '
  # Get all results files and process them in one go
  let files = (ls **/results.txt | get name)
  echo $"Found files: ($files)"

  let matrix = {
    include: (
      $files
      | each { |file| open $file }          # Open each file
      | each { |content| $content | lines }  # Split into lines
      | flatten                             # Flatten the nested lists
      | where { |line| $line != "" }        # Filter empty lines
      | each { |line| 
          # Extract just the version part after the last colon
          let version = ($line | parse "supabase/postgres:{version}" | get version.0)
          {version: $version}
      }
    )
  }

  let json_output = ($matrix | to json -r)  # -r for raw output
  echo $"Debug output: ($json_output)"

  $"matrix=($json_output)" | save --append $env.GITHUB_OUTPUT
'

